def actualErrorCoefficients (η : Character) (u : FreeRow) (P : PrimeIdeal)
    (hs : Supported P.val) (x z : ℂ) : CubicCoefficients :=
  if P.val ∣ Ideal.span {u.val} then actualRamifiedErrorCoefficients η u P hs x z
